INSERT INTO fc_sbc_formations VALUES('FC27',105,'4-3-3','FUTWIZ 세트 페이지 FORMATION 「433」 (https://www.futwiz.com/sbcs/future-stars-challenge-4/65 · URL 번호 65 = EA set_ea_id · 세트 내 챌린지 1개 = challenge_ea_id 105 · 2026-10-22) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — FUTWIZ 표기 「433」을 변형 번호 없는 4-3-3으로 읽었다(변형이면 「433(4)」식일 것으로 본 해석 · 미검증). 조건 원문 6개 fut.gg와 일치. 인게임 기록과 갈리면 인게임 우선','2026-10-21');
INSERT INTO fc_sbc_formations VALUES('FC27',106,'4-4-2','FUTWIZ 세트 페이지 FORMATION 「442」 · TOTAL PLAYERS 10 (https://www.futwiz.com/sbcs/1-of-3-79-gold-player-pick/66 · URL 번호 66 = EA set_ea_id · 세트 내 챌린지 1개 = challenge_ea_id 106 · 2026-10-22) — FUTBIN은 앱 안 브라우저에서 Cloudflare 보안 확인에 막혀 대체','MEDIUM — FUTWIZ 표기 「442」를 4-4-2로 읽었다. 조건 원문(Min Gold · 10명) fut.gg와 일치. 인게임 기록과 갈리면 인게임 우선','2026-10-21');
